def counted_calls(n):
    def counter(fn):
        def wrapper(*args):
            wrapper.calls += 1
            return fn(*args)
        wrapper.calls = 0
        return wrapper
    @counter
    def add(a, b):
        return a + b
    total = sum(add(i, i) for i in range(n))
    return [total, add.calls]

